import{_ as a,o as t,c as o,ag as i}from"./chunks/framework.DyxC4IQh.js";const u=JSON.parse('{"title":"Hint 标签点击","description":"hint 模式的一次完整闭环：扫描窗口、贴标签、敲字母、退出。","frontmatter":{"description":"hint 模式的一次完整闭环：扫描窗口、贴标签、敲字母、退出。"},"headers":[],"relativePath":"guide/hints.md","filePath":"guide/hints.md","lastUpdated":1792208533000}'),c={name:"guide/hints.md"};function d(s,e,n,p,l,r){return t(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="hint-标签点击" tabindex="-1">Hint 标签点击 <a class="header-anchor" href="#hint-标签点击" aria-label="Permalink to &quot;Hint 标签点击&quot;">​</a></h1><p>这是 VimAct 的主用法：给屏幕上每个可点击元素一个短标签，敲标签就点它。</p><h2 id="一次完整闭环" tabindex="-1">一次完整闭环 <a class="header-anchor" href="#一次完整闭环" aria-label="Permalink to &quot;一次完整闭环&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>按 F ──▶ 扫描当前窗口 ──▶ 每个可点击元素贴上标签 ──▶ 敲标签字母</span></span>
<span class="line"><span>   ──▶ 元素被点击 ──▶ 覆盖层消失</span></span></code></pre></div><p>按 <code>Esc</code>、<code>Q</code>，或者再按一次 <code>F</code>，都能在不触发任何点击的情况下退出。hint 模式不会自己超时消失，它一直等到你退出、命中一个标签，或者输入法弹出。</p><h2 id="谁能拿到标签" tabindex="-1">谁能拿到标签 <a class="header-anchor" href="#谁能拿到标签" aria-label="Permalink to &quot;谁能拿到标签&quot;">​</a></h2><p>同时满足三个条件的节点会贴标签：</p><ul><li>节点可点击，判定看 <code>isClickable()</code>，或者节点动作里带 <code>ACTION_CLICK</code> / <code>ACTION_LONG_CLICK</code>。</li><li>节点边界和屏幕有交集，且宽高都大于 0。</li><li>在同一个屏幕里，最多取 400 个目标。超出部分按阅读顺序丢弃。</li></ul><p>可点击的容器不吞掉它内部的元素。一个卡片本身可点，卡片里的按钮同样可点，两者各自拿到标签、各自成层。这是<a href="/vimact-site/guide/cursor.html">方向键光标</a>能钻进容器的基础。</p><p>反过来，自绘控件拿不到标签。游戏画面、<code>SurfaceView</code>、部分图表，只要开发者没有把它们暴露成无障碍节点，VimAct 就看不见它们。WebView 里的网页按浏览器暴露的无障碍树处理，能标多少算多少。</p><h2 id="标签怎么分配" tabindex="-1">标签怎么分配 <a class="header-anchor" href="#标签怎么分配" aria-label="Permalink to &quot;标签怎么分配&quot;">​</a></h2><p>字符集是小写 a–z，去掉当前被占用的控制键，见<a href="/vimact-site/guide/keys.html">键位总览</a>。</p><p>分配看两件事：位置顺序，和长度。</p><p>阅读顺序决定谁拿到短标签——先按纵向（8 像素内算同一行），再按横向。左上角那个元素最先分配。长度上单字符优先，可用字符用完才补两字符，规则保证单字符标签数量取到最多。</p><p>两字符标签也不是无限的。字符集有 base 个字母，一轮最多贴出 base² 个标签：默认字符集 16 个字母（a–z 去掉 <code>f</code>、<code>q</code> 和当前开着的方向键），上限 256 个。关掉一组方向键是 20 个字母、400 个标签，两组全关是 24 个字母，此时 400 个目标都能标上。目标数超过标签数，多出来的那部分不贴标签。</p><p>关键在于标签集合永远前缀无关：没有任何一个标签是另一个标签的前缀。所以敲下 <code>b</code> 的那一刻，如果 <code>b</code> 是屏幕上的标签，它立即生效，不需要等待第二个字母，也不需要担心它挡住了 <code>bc</code>。</p><h2 id="输入过程中" tabindex="-1">输入过程中 <a class="header-anchor" href="#输入过程中" aria-label="Permalink to &quot;输入过程中&quot;">​</a></h2><p>缓冲里的字符实时参与匹配。已经匹配上的标签从黄底变成绿底，你敲第一个字母的时候就能看到候选范围收窄到几个。</p><p>按 <code>Backspace</code> 退一格。缓冲里的内容如果不再是任何标签的前缀，缓冲直接清零——按错了不需要连按退格，重新输入即可。</p><h2 id="标签会不会跳来跳去" tabindex="-1">标签会不会跳来跳去 <a class="header-anchor" href="#标签会不会跳来跳去" aria-label="Permalink to &quot;标签会不会跳来跳去&quot;">​</a></h2><p>hint 模式每 32 毫秒重扫一次屏幕。重扫之后标签尽量不动：节点身份由 <code>viewId</code> + 类名 + 文本（或 <code>contentDescription</code>）拼成，同一个身份在下一次扫描里保留原来的标签，新出现的元素拿空闲标签，消失的元素释放标签。</p><p>列表滚动时同一条目通常保持同一个标签，因为身份没变。</p><p>整套重排只发生在一种情况下：保留下来的标签已经无法与新元素凑成前缀无关集合。此时重排比局部修补更可预测，代价是屏幕上标签会集体变一次。</p><h2 id="点击落在哪里" tabindex="-1">点击落在哪里 <a class="header-anchor" href="#点击落在哪里" aria-label="Permalink to &quot;点击落在哪里&quot;">​</a></h2><p>优先走节点自带的 <code>ACTION_CLICK</code>。这在绝大多数标准控件上够用。</p><p>拿不到结果时改用坐标兜底：对标签所属区域的中心点派发一次 <code>dispatchGesture</code> 合成轻点，历时 50 毫秒。这样自绘但暴露了边界的产品（部分 Flutter、Compose 自定义组件）也能被点到。兜底走的是无障碍手势 API，不需要 shell，也不需要 ADB。</p><p>有一类节点要单独说清楚：只声明长按动作、没有普通点击的（<code>isClickable()</code> 为 false，动作里只有 <code>ACTION_LONG_CLICK</code>）。这类节点照样被采集、照样拿到标签，但按下标签发的仍然是短按，长按才有的动作做不出来，比如长按出菜单、长按进多选。目前代码里没有长按通道，标签亮着不等于那一下会生效。</p>`,27)])])}const b=a(c,[["render",d]]);export{u as __pageData,b as default};
